    camera_motion_type: 'KEN_BURNS', routing: 'LIPSYNC', gpu_priority: 'P2', bgm_hint: { category: 'battle_orchestral', mood: 'anger' }, sfx_hint: ['rain_ambience', 'sword_draw']
  }
