function unpackLibrary(nodeName, requiredField) {
  try {
    const rawItems = $(nodeName).all().map(i => i.json);
    const rows = [];
    for (const entry of rawItems) {
      if (Array.isArray(entry)) { for (const r of entry) { if (r && r[requiredField]) rows.push(r); } }
      else if (entry && entry[requiredField]) { rows.push(entry); }
    }
    return rows;
  } catch (e) { return []; }
}

const bgmCatalog = unpackLibrary('Supabase: Fetch BGM Library', 'file_url');
