const DEFAULT_CC0_BGM = { track_name: 'DEFAULT_CC0_AMBIENT_01', genre: 'default_ambient', mood: 'neutral', file_url: `${$env.SUPABASE_URL}/storage/v1/object/public/assets/global/cc0_ambient_fallback.mp3`, tier_used: 'TIER_3_DEFAULT_CC0' };
