for (const sc of sortedScenes) {
  const reqCategory = (sc.bgm_hint?.category || 'cinematic_anime').toString().toLowerCase().trim();
  const reqMood = (sc.bgm_hint?.mood || sc.emotion || 'neutral').toString().toLowerCase().trim();

  let selectedBgm = null;
  let bgmTier = 'TIER_3_DEFAULT_CC0';

  const tier1Match = bgmCatalog.find(b => (b.genre || '').toString().toLowerCase().trim() === reqCategory && (b.mood || '').toString().toLowerCase().trim() === reqMood);
  const tier2Match = !tier1Match ? bgmCatalog.find(b => (b.genre || '').toString().toLowerCase().trim() === reqCategory) : null;

  if (tier1Match) { selectedBgm = tier1Match; bgmTier = 'TIER_1_EXACT_CATEGORY_MOOD'; tier1BgmCount++; }
  else if (tier2Match) { selectedBgm = tier2Match; bgmTier = 'TIER_2_CATEGORY_ONLY'; tier2BgmCount++; }
  else { selectedBgm = DEFAULT_CC0_BGM; bgmTier = 'TIER_3_DEFAULT_CC0'; tier3BgmCount++; }

  audioUsageLogs.push({ project_id: base.project_id, episode_no: base.episode_no, scene_order: sc.scene_order, audio_type: 'BGM', requested_hint: { category: reqCategory, mood: reqMood }, resolved_code: selectedBgm.track_name || 'DEFAULT_CC0_AMBIENT_01', resolved_url: selectedBgm.file_url, fallback_tier: bgmTier });

  const requestedSfxList = Array.isArray(sc.sfx_hint) ? sc.sfx_hint : [];
  const resolvedSfxList = [];

  for (const rawSfx of requestedSfxList) {
