    if (!sfxQuery) continue;

    const sfxT1 = sfxCatalog.find(s => (s.sfx_name || '').toString().toLowerCase().trim() === sfxQuery);
    const sfxT2 = !sfxT1 ? sfxCatalog.find(s => sfxQuery.includes((s.category || '').toString().toLowerCase().trim()) || (s.category || '').toString().toLowerCase().trim().includes(sfxQuery)) : null;

    let chosenSfx = DEFAULT_SILENCE_SFX;
    let sfxTier = 'TIER_3_SILENCE_FALLBACK';
    if (sfxT1) { chosenSfx = sfxT1; sfxTier = 'TIER_1_EXACT_SFX'; }
    else if (sfxT2) { chosenSfx = sfxT2; sfxTier = 'TIER_2_TYPE_FALLBACK'; sfxFallbackCount++; }
    else { sfxFallbackCount++; }

    resolvedSfxList.push({ sfx_code: chosenSfx.sfx_name || 'DEFAULT_SILENCE_00', audio_url: chosenSfx.file_url || null, fallback_tier: sfxTier });
    audioUsageLogs.push({ project_id: base.project_id, episode_no: base.episode_no, scene_order: sc.scene_order, audio_type: 'SFX', requested_hint: { sfx: sfxQuery }, resolved_code: chosenSfx.sfx_name || 'DEFAULT_SILENCE_00', resolved_url: chosenSfx.file_url || null, fallback_tier: sfxTier });
